#include <stdio.h>
int main(void) {
    // 입력값을 바꿔도 같은 원리로 풀어요.
    int a, b;
    if (scanf("%d %d", &a, &b) != 2) return 1;
    // 주소를 저장할 포인터예요.
    int *p = &b;
    // 주소 숫자가 아니라 가리킨 값을 출력해요.
    printf("%d\n", *p);
    return 0;
}

